let text = $json.output || "";

// Force clean bullet formatting
text = text
  .replace(/\s-\s/g, '\n• ')
  .replace(/Eligibility conditions:/i, '\n\n**Eligibility conditions:**')
  .replace(/Non-returnable items include:/i, '\n\n**Non-returnable items include:**');

// Ensure link is clickable (Markdown)
text = text.replace(
  /(https?:\/\/www\.blushu\.in\/policies\/refund-policy)/g,
  '[View full Refund Policy]($1)'
);

return {
  output: text.trim()
};
